select we.id, we.event_time
from web_events we
where we.session_id in (9, 15, 31, 37) and we.session_id not in (select id from sessions where browser = 'Edge');

select we.id, we.event_time, we.page
from web_events we
where we.session_id in (3, 5, 26) and we.session_id not in (select id from sessions where customer_id = 18);

SELECT a.id, a.balance, a.account_type
FROM accounts a
WHERE a.opened_date < '2023-10-01' AND EXISTS (SELECT 1 FROM transactions t WHERE t.account_id = a.id);

select *, case when duration_sec >= 408 then 'High' when duration_sec >= 118 then 'Medium' else 'Low' end as duration_sec_level
from web_events
where not (session_id in (3, 18) and page = '/cart' and session_id in (3, 5, 14));

select *
from (
    select *, row_number() over (partition by store_id order by last_restock desc, id) as rn
    from inventory
    where last_restock < '2023-06-01'
) as t
where rn = 1;

SELECT last_restock
FROM inventory
WHERE YEAR(last_restock) = 2025 AND quantity != 168;

SELECT i.store_id, i.quantity, ss.revenue
FROM inventory i
LEFT JOIN store_sales ss ON i.store_id = ss.store_id AND i.product_id = ss.product_id;

SELECT *
FROM departments
WHERE dept_name = 'Engineering';

SELECT *
FROM order_items
WHERE quantity != 7 AND unit_price > 260;

SELECT *
FROM store_sales
WHERE units <= 26 AND units < 13;
